#' L1000PAIResult class
#'
#' Container for results generated by L1000PAI.
#'
#' @slot input_rank A named numeric vector of ranked genes.
#' @slot gsea_table A data.frame of raw enrichment results.
#' @slot pair_table A data.frame of final result rows.
#' @slot metadata A list of analysis metadata.
#'
#' @name L1000PAIResult-class
#' @rdname L1000PAIResult-class
#' @exportClass L1000PAIResult
setClass(
  "L1000PAIResult",
  slots = c(
    input_rank = "numeric",
    gsea_table = "data.frame",
    pair_table = "data.frame",
    metadata = "list"
  )
)

setMethod("show", "L1000PAIResult", function(object) {
  cat("L1000PAIResult\n")
  cat("  Ranked genes:", length(object@input_rank), "\n")
  cat("  GSEA rows:", nrow(object@gsea_table), "\n")
  cat("  Final rows:", nrow(object@pair_table), "\n")
  if (!is.null(object@metadata$library)) {
    cat("  Library:", object@metadata$library, "\n")
  }
  if (!is.null(object@metadata$library_mode_used)) {
    cat("  Mode:", object@metadata$library_mode_used, "\n")
  }
})
#' @import methods
NULL
#' Construct an L1000PAIResult object
#'
#' @param input_rank A named numeric vector of ranked genes.
#' @param gsea_table A data.frame of raw enrichment results.
#' @param pair_table A data.frame of paired activity results.
#' @param metadata A list of metadata.
#'
#' @return An object of class `L1000PAIResult`.
#' @export
L1000PAIResult <- function(input_rank, gsea_table, pair_table, metadata = list()) {
  methods::new(
    "L1000PAIResult",
    input_rank = input_rank,
    gsea_table = gsea_table,
    pair_table = pair_table,
    metadata = metadata
  )
}
